import React, { useState, useEffect, useRef } from "react";
import Header from "./../../components/Header/Header";
import Footer from "./../../components/Footer/Footer";
import "./homepage.css";
import { useNavigate } from "react-router-dom";

const HomePage: React.FC = () => {
  // ... (keep all your existing state declarations)

  // Modified fetchQuestions function
  const fetchQuestions = async () => {
    const email = localStorage.getItem("userEmail");
    
    // Clear any existing test data when starting fresh
    localStorage.removeItem("test_id");
    localStorage.removeItem("resume_test_data");

    if (!email) {
      alert("User email is missing. Please log in again.");
      navigate("/login");
      return;
    }

    try {
      let response;
      const testId = localStorage.getItem("test_id");

      // Check for resume data
      const resumeTestData = localStorage.getItem("resume_test_data");
      if (resumeTestData) {
        const data = JSON.parse(resumeTestData);
        setQuestions(data.questions || []);
        localStorage.removeItem("resume_test_data");
        return;
      }

      if (testId) {
        // Resume existing test
        response = await fetch("http://127.0.0.1:5000/resume", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ testId }),
        });
      } else {
        // Start new test - clear any old test data first
        localStorage.removeItem("test_id");

        const numQuestions = localStorage.getItem("numQuestions");
        const selectedTopics = JSON.parse(localStorage.getItem("selectedTopics") || "[]");

        if (!numQuestions || selectedTopics.length === 0) {
          alert("Required details are missing. Please go back to the details page.");
          navigate("/dashboard");
          return;
        }

        response = await fetch("http://127.0.0.1:5000/start_test", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            email,
            numQuestions: parseInt(numQuestions),
            selectedTopics,
          }),
        });

        // Store the new test ID if the request was successful
        if (response.ok) {
          const data = await response.json();
          if (data.test_id) {
            localStorage.setItem("test_id", data.test_id.toString());
          }
        }
      }

      if (response.ok) {
        const data = await response.json();
        setQuestions(data.questions || []);
      } else {
        console.error("Failed to fetch questions");
        alert("Failed to fetch questions. Please try again.");
      }
    } catch (error) {
      console.error("Error fetching questions:", error);
      alert("An error occurred while fetching questions.");
    }
  };

  // Modified submitAnswersToBackend function
  const submitAnswersToBackend = async () => {
    const userEmail = localStorage.getItem("userEmail");
    const testId = localStorage.getItem("test_id");

    if (!userEmail) {
      alert("Please log in to submit answers");
      navigate("/login");
      return;
    }

    if (!testId) {
      alert("No test session found");
      return;
    }

    try {
      const formattedAnswers = questions.map((question) => {
        const userAnswer = answers.find((ans) => ans.id === question.id);
        return {
          id: question.id,
          answer: userAnswer?.answer || "",
          time_taken: userAnswer?.time_taken || 0,
        };
      });

      const response = await fetch("http://localhost:5000/submit_answers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          rollno: userEmail,
          testid: testId,
          answers: formattedAnswers,
        }),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Failed to submit answers");
      }

      alert(result.message || "Answers submitted successfully!");
      setIsTestFinished(true);
      
      // Clear test data after successful submission
      localStorage.removeItem("test_id");
      localStorage.removeItem("answers");
    } catch (error) {
      console.error("Submission error:", error);
      alert("Error submitting answers. Please try again.");
    }
  };
  // Handle feedback submission
  const handleFeedbackSubmit = () => {
    if (feedback1.trim() === "" || feedback2.trim() === "") {
      alert("Please provide the feedback.");
      return;
    }
    submitFeedback();
  };

  // Submit feedback to the backend
  const submitFeedback = async () => {
    try {
      const response = await fetch("http://127.0.0.1:5000/submit_feedback", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          feedback1: feedback1,
          feedback2: feedback2,
        }),
      });

      if (response.ok) {
        alert("Thank you for the feedback!");
        navigate("/dashborad");
      } else {
        console.error("Failed to submit Feedback");
        alert("Failed to submit Feedback. Please try again.");
      }
    } catch (error) {
      console.error("Error submitting Feedback:", error);
      alert("An error occurred while submitting Feedback.");
    }
  };

  // Start the timer when the question changes
  useEffect(() => {
    startTimeRef.current = Date.now(); // Start the timer for the current question
    setElapsedTime(0); // Reset the elapsed time for the current question

    const timerInterval = setInterval(() => {
      setElapsedTime((prev) => prev + 1); // Increment the elapsed time every second
    }, 1000);

    return () => clearInterval(timerInterval); // Cleanup the interval on component unmount or question change
  }, [currentQuestionIndex]);

  return (
    <div className="home">
      <Header />
      <div className="home-content">
        {isTestFinished ? (
          <div className="feedback-form">
            <h2>Feedback Form</h2>
            <div>
              <label>
                How helpful did you find the mock interview system in preparing for real interviews?
                <input
                  type="text"
                  value={feedback1}
                  onChange={(e) => setFeedback1(e.target.value)}
                  placeholder="Enter your feedback"
                />
              </label>
            </div>
            <div>
              <label>
                Do you have any suggestions or improvements for enhancing the mock interview system?
                <input
                  type="text"
                  value={feedback2}
                  onChange={(e) => setFeedback2(e.target.value)}
                  placeholder="Enter your feedback"
                />
              </label>
            </div>
            <button onClick={handleFeedbackSubmit}>Submit Feedback</button>
            <br />
            <br />
            <button onClick={() => navigate("/dashborad")}>Skip</button>
          </div>
        ) : (
          <>
            {questions.length > 0 ? (
              <div className="question-container">
                <h2>Question {currentQuestionIndex + 1}</h2>
                <p>{questions[currentQuestionIndex].question}</p>
                <div className="input-speaker">
                  <input
                    type="text"
                    value={answer}
                    onChange={(e) => setAnswer(e.target.value)}
                    className="answer-textbox"
                    placeholder="Type your answer here..."
                  />
                  <button
                    onClick={() => {
                      speakText(questions[currentQuestionIndex].question);
                    }}
                    className="speaker-button"
                  >
                    <span role="img" aria-label="Speaker">🔊</span>
                  </button>
                  <button
                    className={`mic-button ${isListening ? "active" : ""}`}
                    title={isListening ? "Click to stop recording" : "Click to start recording"}
                    onClick={handleMicClick}
                  >
                    <span role="img" aria-label="Microphone">🎤</span>
                  </button>
                </div>

                <div className="controls">
                  
                  <button onClick={handleAnswerSubmit} className="submit-button">
                    {currentQuestionIndex === questions.length - 1 ? "Finish Test" : "Next Question"}
                  </button>
                  <br />
                  <button
                    onClick={() => setIsTTSActive(!isTTSActive)}
                    className="tts-toggle-button"
                  >
                    {isTTSActive ? "Disable Text-to-Speech" : "Enable Text-to-Speech"}
                  </button>
                 
                </div>
                <div className="voiceSelect">
                <select
                    value={selectedVoice ? selectedVoice.name : ""}
                    onChange={(e) => {
                      const voice = voices.find((v) => v.name === e.target.value);
                      if (voice) setSelectedVoice(voice);
                    }}
                    className="voice-select"
                  >
                    {voices.map((voice) => (
                      <option key={voice.name} value={voice.name}>
                        {voice.name} ({voice.lang})
                      </option>
                    ))}
                  </select>
                </div>
                <div className="timer">
                  <p>Time Elapsed: {elapsedTime} seconds</p>
                </div>
              </div>
            ) : (
              <p>Loading questions...</p>
            )}
          </>
        )}
        <img src="/AIbot.jpg" alt="Visual Representation" className="question-image" />
      </div>
      <Footer />
    </div>
  );
};

export default HomePage;
